Use `pg` (node-postgres) with `Pool`:

```js
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT ?? '5432'),
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                // max connections
  min: 2,                 // keep alive connections
  idleTimeoutMillis: 30_000,    // close idle after 30s
  connectionTimeoutMillis: 5_000, // fail if can't connect in 5s
  allowExitOnIdle: false,
});

// Catch pool-level errors (e.g. dropped connections)
pool.on('error', (err) => {
  console.error('Unexpected pool error', err);
  // Don't crash — pool auto-recovers
});
```

**Query with error handling:**

```js
async function query(sql, params) {
  const client = await pool.connect(); // throws if connectionTimeout exceeded
  try {
    const result = await client.query(sql, params);
    return result.rows;
  } catch (err) {
    // Optionally: detect retryable errors (e.g. 40001 serialization_failure)
    throw err;
  } finally {
    client.release(); // always release, even on error
  }
}
```

**For transactions:**

```js
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
```

**Graceful shutdown:**

```js
process.on('SIGTERM', async () => {
  await pool.end(); // waits for active queries to finish
  process.exit(0);
});
```

Key points:
- `pool.query()` fine for one-off queries (auto-acquire/release), but use `pool.connect()` for transactions
- `client.release(true)` destroys connection instead of returning to pool — use on unrecoverable errors
- Set `max` based on Postgres `max_connections` minus connections reserved for other apps/admin
